using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata retrieval ──
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Type        : {personInfo.Type.Name}");
Console.WriteLine($"Kind        : {personInfo.Kind}");
Console.WriteLine($"Properties  : {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// ── 2. Probe without throwing ──
// TryGetTypeInfo returns false instead of throwing when metadata isn't available.
// Use a resolver that knows about nothing to demonstrate the "miss" path.
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nFound metadata for Person: {info!.Type.Name}");
}
else
{
    Console.WriteLine("\nNo metadata for Person — and no exception was thrown.");
}

// Also show the "hit" path with the real resolver:
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2))
{
    Console.WriteLine($"TryGet hit  : {info2!.Type.Name} (Kind={info2.Kind})");
}

// ── Types ──
record Person(string FirstName, string LastName, int Age);

// A resolver that deliberately resolves nothing.
sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

